        let ri: i32 = tb_rows_of(rw, RWS);
        let mut sumy: i64 = 0 as i64;
        let mut sums: i64 = 0 as i64;
        let mut x0: i32 = 2000000000;
        let mut x1: i32 = -2000000000;
        let mut y0: i32 = 2000000000;
        let mut y1: i32 = -2000000000;
        let mut k: i32 = i;
        while k < j {
            let wk: i32 = crate::port::cells_at(wl, k);
            sumy = (sumy).wrapping_add(tb_bkey(wd, wk, ppm) as i64);
            sums = (sums).wrapping_add(tb_max(1, wd_get(wd, wk, wf_size())) as i64);
            if wd_get(wd, wk, hd_x0()) < x0 {
                x0 = wd_get(wd, wk, hd_x0());
            }
            if wd_get(wd, wk, hd_x1()) > x1 {
                x1 = wd_get(wd, wk, hd_x1());
            }
            if wd_get(wd, wk, hd_y0()) < y0 {
                y0 = wd_get(wd, wk, hd_y0());
            }
            if wd_get(wd, wk, hd_y1()) > y1 {
                y1 = wd_get(wd, wk, hd_y1());
            }
            k += 1;
        }
        let cnt: i32 = j - i;
        let size: i32 = (sums / (cnt as i64)) as i32;
        let thr: i32 = (size * SEG_NUM) / SEG_DEN;
        let sf: i32 = tb_rows_of(sg, SGS);
        let sty: i32 = tb_currency_style(wd, et, wl, i, j - i);
        let mut cstart: i32 = i;
        let mut cmax: i32 = wd_get(wd, crate::port::cells_at(wl, i), hd_x1());
        crate::port::cells_push(rw, i);
        crate::port::cells_push(rw, cnt);
        crate::port::cells_push(rw, (sumy / (cnt as i64)) as i32);
        crate::port::cells_push(rw, size);
        crate::port::cells_push(rw, x0);
        crate::port::cells_push(rw, x1);
        crate::port::cells_push(rw, y0);
        crate::port::cells_push(rw, y1);
        crate::port::cells_push(rw, sf);
        crate::port::cells_push(rw, 0);
        k = i + 1;
        while k <= j {
            if (k == j) || ((sty == 1) && ((((k + 1) < j) && tb_currency_lead(wd, et, crate::port::cells_at(wl, k), crate::port::cells_at(wl, k + 1))) && tb_word_digit(wd, et, crate::port::cells_at(wl, k - 1)))) || (((wd_get(wd, crate::port::cells_at(wl, k), hd_x0()) - cmax) > thr) && !tb_glued(wd, et, crate::port::cells_at(wl, k - 1), crate::port::cells_at(wl, k), sty)) {
                crate::port::cells_push(sg, ri);
                crate::port::cells_push(sg, wd_get(wd, crate::port::cells_at(wl, cstart), hd_x0()));
                crate::port::cells_push(sg, cmax);
                crate::port::cells_push(sg, cstart);
                crate::port::cells_push(sg, k - cstart);
                crate::port::cells_push(sg, 0);
                if k < j {
                    cstart = k;
                    cmax = wd_get(wd, crate::port::cells_at(wl, k), hd_x1());
                }
            }
            if k < j {
                if wd_get(wd, crate::port::cells_at(wl, k), hd_x1()) > cmax {
                    cmax = wd_get(wd, crate::port::cells_at(wl, k), hd_x1());
                }
            }
            k += 1;
        }
        crate::port::cells_set(rw, (ri * RWS) + 9, tb_rows_of(sg, SGS) - sf);
