    let nrows: i32 = crate::port::cells_at(tb, b + 7);
    let cfirst: i32 = crate::port::cells_at(tb, b + 9);
    let cend: i32 = cfirst + crate::port::cells_at(tb, b + 10);
    let mut c: i32 = cfirst;
    let mut ne: i32 = 0;
    let mut nw: i32 = 0;
