                let lw2: i32 = crate::port::cells_at(tw, crate::port::cells_at(tc, (c * TCS) + 8) + (cn - 1));
                let c0: i32 = crate::port::cells_at(et, wd_get(wd, fw, hd_tstart()));
                let ts2: i32 = wd_get(wd, lw2, hd_tstart());
                let tl2: i32 = wd_get(wd, lw2, hd_tlen());
